-- Rows are skipped when the part or the record is missing, or when the pair is already linked in any way.

-- interdisciplinary-lpm-synth: 8 proposals
INSERT INTO curriculum_repository_links (project_id, data_object_id, repository_record_id, relation_type, rationale)
SELECT o.project_id, o.id, r.id, v.relation_type, v.rationale
FROM (VALUES
  ('04d57493-ac2f-5ec6-a1ba-0596eae3158a', 'deutsche-lpm', 'DELP-EVENT-thueringen-biologie-gymnasium-2026-erprobungsfassung', 'proposed_relates_to', 'In the 2026 trial Lehrplan for Biologie at the Gymnasium, the topics "Genetics", "Passing on genetic information", "Variability of traits", "Human genetics (applying genetic knowledge)" and others (grade 10/11) cover the concepts of this part (Inheritance, Variation). Two AI tagging passes of 2 November agreed on the match and it rests on the Lehrplan wording. Thüringen meets these topics later than this part''s band (K-2). No person has checked it.'),
  ('396e3dd9-4f22-5160-b6c7-3752caefa1b8', 'deutsche-lpm', 'DELP-EVENT-thueringen-biologie-gymnasium-2026-erprobungsfassung', 'proposed_relates_to', 'In the 2026 trial Lehrplan for Biologie at the Gymnasium, the topics "Connections in evolutionary biology", "Genetics", "Evolution", "Passing on genetic information" and others (grade 10/11/11/12) touch the concepts of this part (Evolutionary Process, Inheritance, Selection, Transmission, Variation). Two AI tagging passes of 2 November agreed on the match and it rests on the Lehrplan wording. Thüringen meets these topics in grades 10 to 12, which is inside this part''s band (9-12). No person has checked it. The part compares four disciplines, and the Lehrplan topics hold the biological one only.'),
  ('6315aad7-35b7-52dc-9dd2-1b82d707a768', 'deutsche-lpm', 'DELP-EVENT-thueringen-biologie-gymnasium-2026-erprobungsfassung', 'proposed_relates_to', 'In the 2026 trial Lehrplan for Biologie at the Gymnasium, the topics "Connections in evolutionary biology", "Evolution", "Development of life", "Genetics" and others (grade 10/11/11/12) cover the concepts of this part (Evolutionary Process, Information, Selection, Transmission, Variation). Two AI tagging passes of 2 November agreed on the match and it rests on the Lehrplan wording. Thüringen meets these topics later than this part''s band (6-8). No person has checked it.'),
  ('6f04ee30-2be3-537b-9d0e-b339d9fed79c', 'deutsche-lpm', 'DELP-EVENT-thueringen-biologie-gymnasium-2026-erprobungsfassung', 'proposed_relates_to', 'In the 2026 trial Lehrplan for Biologie at the Gymnasium, the topics "Reproduction, development and sexuality", "Human biology" (grade 7/8) touch the concepts of this part (Development). Two AI tagging passes of 2 November agreed on the match and it rests on the Lehrplan wording. Thüringen meets these topics later than this part''s band (K-2). No person has checked it. The part is about growth and change with age, and the topics are about reproduction and development in biology, so the match is loose.'),
  ('db1fca08-0dcf-5910-a3df-2de902e8630a', 'deutsche-lpm', 'DELP-EVENT-thueringen-biologie-gymnasium-2026-erprobungsfassung', 'proposed_relates_to', 'In the 2026 trial Lehrplan for Biologie at the Gymnasium, the topics "Genetics", "Passing on genetic information", "Human genetics (applying genetic knowledge)", "Molecular genetic basis of life" and others (grade 10/11/11/12) cover the concepts of this part (Inheritance, Transmission, Variation). Two AI tagging passes of 2 November agreed on the match and it rests on the Lehrplan wording. Thüringen meets these topics later than this part''s band (3-5). No person has checked it.'),
  ('9fc65a59-5de1-51ad-ad30-a9c0faca177a', 'deutsche-lpm', 'DELP-EVENT-thueringen-mnt-gymnasium-2026-erprobungsfassung', 'proposed_relates_to', 'In the 2026 trial Lehrplan for Mensch-Natur-Technik at the Gymnasium, the topics "10.1 The hook-and-loop fastener", "Relations between humans, nature and technology", "10.2 Lightweight construction", "10.3 From the fog-drinking beetle to drinking water" and others (grade 5/6) touch the concepts of this part (Technology). Two AI tagging passes of 2 November agreed on the match and it rests on the Lehrplan wording. Thüringen meets these topics later than this part''s band (K-2). No person has checked it. The bionics topics are about copying technical ideas from nature, while the part asks for a tool and what it helps people do, so the match is loose.'),
  ('5e4cdc6e-5c25-5f21-a833-4c0859a609da', 'deutsche-lpm', 'DELP-MANDATE-bayern-faecheruebergreifend-zweistufig', 'proposed_contrasts_with', 'Bayern has two tiers of work across subjects (fachuebergreifend and faecherverbindend) and none in which subjects merge into one (faecherintegrierend). This strand teaches one idea, selection, across biology, culture, education and AI, which is a merged treatment. Whether Bayern would place such a strand inside a subject is unknown.'),
  ('5e4cdc6e-5c25-5f21-a833-4c0859a609da', 'deutsche-lpm', 'DELP-MANDATE-sachsen-massnahme-2-2-faecherverbindender-unterricht', 'proposed_relates_to', 'Sachsen asks that every Lehrplan theme is reviewed for its potential to be linked with other subjects. This strand is built on links between subjects, so it can serve as an example of what such a review could produce. The record gives the measure only and names no content.')
) AS v(object_id, source_repo, source_record_id, relation_type, rationale)
JOIN lpm_data_objects o ON o.id = v.object_id::uuid
JOIN curriculum_repository_records r ON r.source_repo = v.source_repo AND r.source_record_id = v.source_record_id
WHERE NOT EXISTS (SELECT 1 FROM curriculum_repository_links x WHERE x.data_object_id = o.id AND x.repository_record_id = r.id);

-- bio-core-lpm-synth: 11 proposals
INSERT INTO curriculum_repository_links (project_id, data_object_id, repository_record_id, relation_type, rationale)
SELECT o.project_id, o.id, r.id, v.relation_type, v.rationale
FROM (VALUES
  ('4f1b4d5d-6232-5ef5-b44c-a850224b58a5', 'deutsche-lpm', 'DELP-EVENT-thueringen-biologie-gymnasium-2026-erprobungsfassung', 'proposed_relates_to', 'In the 2026 trial Lehrplan for Biologie at the Gymnasium, the topics "Development of life", "Connections in evolutionary biology", "Evolution", "Content area: Diversity of life" and others (grade 10/11/11/12) cover the concepts of this part (Drift, Fitness, Gene, Mutation, Natural Selection). Two AI tagging passes of 2 November agreed on the match and it rests on the Lehrplan wording. Thüringen meets these topics later than this part''s band (6-8). No person has checked it.'),
  ('60df174a-b374-5cd1-9d06-9d76ecc4af9f', 'deutsche-lpm', 'DELP-EVENT-thueringen-biologie-gymnasium-2026-erprobungsfassung', 'proposed_relates_to', 'In the 2026 trial Lehrplan for Biologie at the Gymnasium, the topics "Evolution", "Human evolution" (grade 10/11) touch the concepts of this part (Drift, Mutation, Phylogeny). Two AI tagging passes of 2 November agreed on the match and it rests on the Lehrplan wording. Thüringen meets these topics in grades 10 to 12, which is inside this part''s band (9-12). No person has checked it.'),
  ('6c0b740a-cb12-5c3d-8a32-75fc01624ddf', 'deutsche-lpm', 'DELP-EVENT-thueringen-biologie-gymnasium-2026-erprobungsfassung', 'proposed_relates_to', 'In the 2026 trial Lehrplan for Biologie at the Gymnasium, the topics "Connections in evolutionary biology", "Genetics" (grade 10/11) touch the concepts of this part (Allele, Drift, Gene, Mutation, Population). Two AI tagging passes of 2 November agreed on the match and it rests on the Lehrplan wording. Thüringen meets these topics in grades 10 to 12, which is inside this part''s band (9-12). No person has checked it.'),
  ('70cf40f5-cb5d-508a-95dc-d18eaa465e94', 'deutsche-lpm', 'DELP-EVENT-thueringen-biologie-gymnasium-2026-erprobungsfassung', 'proposed_relates_to', 'In the 2026 trial Lehrplan for Biologie at the Gymnasium, the topics "Genetics", "Passing on genetic information", "Human genetics (applying genetic knowledge)", "Storage of genetic information" and others (grade 10/11) cover the concepts of this part (Inheritance). Two AI tagging passes of 2 November agreed on the match and it rests on the Lehrplan wording. Thüringen meets these topics later than this part''s band (3-5). No person has checked it.'),
  ('8a1c0b8f-8e98-526f-bd7a-8cb2795daa85', 'deutsche-lpm', 'DELP-EVENT-thueringen-biologie-gymnasium-2026-erprobungsfassung', 'proposed_relates_to', 'In the 2026 trial Lehrplan for Biologie at the Gymnasium, the topics "Genetics", "Expression of genetic information", "Variability of traits", "Molecular genetic basis of life" and others (grade 10/11/11/12) cover the concepts of this part (Allele, Gene, Mutation). Two AI tagging passes of 2 November agreed on the match and it rests on the Lehrplan wording. Thüringen meets these topics later than this part''s band (6-8). No person has checked it.'),
  ('8e62e70a-437d-540d-83f6-90a0fe54783a', 'deutsche-lpm', 'DELP-EVENT-thueringen-biologie-gymnasium-2026-erprobungsfassung', 'proposed_relates_to', 'In the 2026 trial Lehrplan for Biologie at the Gymnasium, the topics "Genetics", "Passing on genetic information", "Human genetics (applying genetic knowledge)", "Storage of genetic information" and others (grade 10/11) cover the concepts of this part (Inheritance). Two AI tagging passes of 2 November agreed on the match and it rests on the Lehrplan wording. Thüringen meets these topics later than this part''s band (K-2). No person has checked it.'),
  ('aac5e307-a98f-50c6-ba5d-5cc6bcd7ebdf', 'deutsche-lpm', 'DELP-EVENT-thueringen-biologie-gymnasium-2026-erprobungsfassung', 'proposed_relates_to', 'In the 2026 trial Lehrplan for Biologie at the Gymnasium, the topics "Connections in evolutionary biology", "Evolution", "Development of life" (grade 10/11/11/12) cover the concepts of this part (Adaptation). Two AI tagging passes of 2 November agreed on the match and it rests on the Lehrplan wording. Thüringen meets these topics later than this part''s band (K-2). No person has checked it.'),
  ('ae85f5be-aead-5819-99df-8b3d431f79d1', 'deutsche-lpm', 'DELP-EVENT-thueringen-biologie-gymnasium-2026-erprobungsfassung', 'proposed_relates_to', 'In the 2026 trial Lehrplan for Biologie at the Gymnasium, the topics "Connections in evolutionary biology", "Evolution", "Development of life", "Content area: Diversity of life" and others (grade 10/11/11/12) cover the concepts of this part (Adaptation, Inheritance, Natural Selection). Two AI tagging passes of 2 November agreed on the match and it rests on the Lehrplan wording. Thüringen meets these topics later than this part''s band (3-5). No person has checked it.'),
  ('b8bf5ec4-fe31-593a-8177-15b8109517b4', 'deutsche-lpm', 'DELP-EVENT-thueringen-biologie-gymnasium-2026-erprobungsfassung', 'proposed_relates_to', 'In the 2026 trial Lehrplan for Biologie at the Gymnasium, the topics "Connections in evolutionary biology", "Evolution", "Development of life" (grade 10/11/11/12) cover the concepts of this part (Adaptation, Drift, Fitness, Mutation, Population). Two AI tagging passes of 2 November agreed on the match and it rests on the Lehrplan wording. Thüringen meets these topics in grades 10 to 12, which is inside this part''s band (9-12). No person has checked it.'),
  ('ca152c60-d9a5-509f-afdb-e2e7bdf983b4', 'deutsche-lpm', 'DELP-EVENT-thueringen-biologie-gymnasium-2026-erprobungsfassung', 'proposed_relates_to', 'In the 2026 trial Lehrplan for Biologie at the Gymnasium, the topics "Connections in evolutionary biology", "Evolution", "Human evolution", "Development of life" and others (grade 10/11/11/12) cover the concepts of this part (Natural Selection, Phylogeny, Population, Speciation). Two AI tagging passes of 2 November agreed on the match and it rests on the Lehrplan wording. Thüringen meets these topics later than this part''s band (6-8). No person has checked it.'),
  ('d8df353a-aa76-5d37-b5b4-a0cd3f1d4860', 'deutsche-lpm', 'DELP-MANDATE-sachsen-anhalt-grundsatzband-doppeljahrgaenge', 'proposed_contrasts_with', 'Sachsen-Anhalt sets competence targets per combined Doppeljahrgang (5/6, 7/8). The model sets stages in bands (K-2, 3-5, 6-8, 9-12). The same contrast is recorded for Thüringen, Sachsen and Bayern. Whether any stage of this strand fits a Doppeljahrgang has not been checked.')
) AS v(object_id, source_repo, source_record_id, relation_type, rationale)
JOIN lpm_data_objects o ON o.id = v.object_id::uuid
JOIN curriculum_repository_records r ON r.source_repo = v.source_repo AND r.source_record_id = v.source_record_id
WHERE NOT EXISTS (SELECT 1 FROM curriculum_repository_links x WHERE x.data_object_id = o.id AND x.repository_record_id = r.id);

-- social-core-lpm-synth: 2 proposals
INSERT INTO curriculum_repository_links (project_id, data_object_id, repository_record_id, relation_type, rationale)
SELECT o.project_id, o.id, r.id, v.relation_type, v.rationale
FROM (VALUES
  ('ec43321e-dd60-5bd9-bdfc-2e4e17dd7b85', 'deutsche-lpm', 'DELP-EVENT-thueringen-biologie-gymnasium-2026-erprobungsfassung', 'proposed_relates_to', 'In the 2026 trial Lehrplan for Biologie at the Gymnasium, the topics "Human evolution", "Evolution" (grade 10/11) cover the concepts of this part (Culture, Social Change). Two AI tagging passes of 2 November agreed on the match and it rests on the Lehrplan wording. Thüringen meets these topics later than this part''s band (K-2). No person has checked it. The topic is in Biologie. Whether its text deals with social change, or only the biological side of human evolution, has not been checked.'),
  ('fd772a6a-0dd8-5410-96c5-79f75443183c', 'deutsche-lpm', 'DELP-EVENT-thueringen-biologie-gymnasium-2026-erprobungsfassung', 'proposed_relates_to', 'In the 2026 trial Lehrplan for Biologie at the Gymnasium, the topics "Human evolution", "Evolution" (grade 10/11) cover the concepts of this part (Culture, Social Change). Two AI tagging passes of 2 November agreed on the match and it rests on the Lehrplan wording. Thüringen meets these topics later than this part''s band (6-8). No person has checked it. The topic is in Biologie. Whether its text deals with social change, or only the biological side of human evolution, has not been checked.')
) AS v(object_id, source_repo, source_record_id, relation_type, rationale)
JOIN lpm_data_objects o ON o.id = v.object_id::uuid
JOIN curriculum_repository_records r ON r.source_repo = v.source_repo AND r.source_record_id = v.source_record_id
WHERE NOT EXISTS (SELECT 1 FROM curriculum_repository_links x WHERE x.data_object_id = o.id AND x.repository_record_id = r.id);

-- computational-core-lpm-synth: 4 proposals
INSERT INTO curriculum_repository_links (project_id, data_object_id, repository_record_id, relation_type, rationale)
SELECT o.project_id, o.id, r.id, v.relation_type, v.rationale
FROM (VALUES
  ('37a89183-dce2-506d-a724-968c6ec03d06', 'openlpm-starter-draft', 'DE-MANDATE-kmk-strategie-bildung-in-der-digitalen-welt-2016', 'proposed_relates_to', 'The KMK strategy sets six digital competence areas for all subjects. One is searching, processing and storing information, which matches this strand''s route from sorting and labelling to recording and encoding data. The record gives only the area names. What pupils do in each area is unchecked.'),
  ('7d846794-560b-58b9-a9f0-267a680c308d', 'openlpm-starter-draft', 'DE-MANDATE-kmk-epa-informatik-abitur-2004', 'proposed_relates_to', 'The Abitur requirements for Informatik describe competences, content and three levels of task demand. The record names no content, so the match with the end of this strand (correctness and efficiency at 9-12) is a guess to check against the EPA text.'),
  ('7d846794-560b-58b9-a9f0-267a680c308d', 'deutsche-lpm', 'DELP-EVENT-thueringen-mbi-introduced', 'proposed_relates_to', 'Thüringen introduces Medienbildung und Informatik as a subject. This strand is the model''s run of computing from following steps to testing programs. The record gives the title and a date only, so the topics taught are unknown.'),
  ('7d846794-560b-58b9-a9f0-267a680c308d', 'deutsche-lpm', 'DELP-EVENT-sl-gems-lehrplan-batch-2025', 'proposed_relates_to', 'The Saarland Gemeinschaftsschule curricula of 2025/26 include an integrated Informatik. This strand is the model''s run of computing. The record rests on a newspaper article, and the curriculum PDFs could not be read, so the topics are unknown.')
) AS v(object_id, source_repo, source_record_id, relation_type, rationale)
JOIN lpm_data_objects o ON o.id = v.object_id::uuid
JOIN curriculum_repository_records r ON r.source_repo = v.source_repo AND r.source_record_id = v.source_record_id
WHERE NOT EXISTS (SELECT 1 FROM curriculum_repository_links x WHERE x.data_object_id = o.id AND x.repository_record_id = r.id);
